def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    store_lead = state_view.captured[player_id] - state_view.captured[1 - player_id]
    side_lead = sum(state_view.board[start:start + 6]) - sum(state_view.board[other:other + 6])
    return max(-10.0, min(10.0, (2.0 * store_lead + 0.25 * side_lead) / 3.0))

def evaluate_state(state_view, player_id):
    start = player_id * 6
    other = (1 - player_id) * 6
    my_total = state_view.captured[player_id] + sum(state_view.board[start:start + 6])
    their_total = state_view.captured[1 - player_id] + sum(state_view.board[other:other + 6])
    return max(-10.0, min(10.0, (my_total - their_total) / 2.4))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    score = captured + own - 0.5 * opp
    return max(-10.0, min(10.0, float(score)))

def evaluate_state(state_view, player_id):
    if player_id == 0:
        own = sum(state_view.board[0:6])
        opp = sum(state_view.board[6:12])
        captured = state_view.captured[0] - state_view.captured[1]
    else:
        own = sum(state_view.board[6:12])
        opp = sum(state_view.board[0:6])
        captured = state_view.captured[1] - state_view.captured[0]
    if state_view.current_player == player_id:
        mobility = len(state_view.legal_actions)
        sign = 1.0
    else:
        mobility = len(state_view.legal_actions)
        sign = -1.0
    score = captured + own - opp + 0.4 * sign * mobility
    return max(-10.0, min(10.0, float(score)))

